"""Install SUPPORT retrieval parity + typed-fact discovery.

Run from ~/freca/core_v1 after:
- direction-aware counterevidence retrieval patch is installed;
- evidence_nature_v1.py is EvidenceNature v1.1.

Only retrieve_requirement_candidates() is replaced.
"""

from __future__ import annotations

import ast
from pathlib import Path

TARGET = Path("evidence_reasoning_v2.py")
NATURE = Path("evidence_nature_v1.py")

if not TARGET.exists():
    raise SystemExit(
        "Missing evidence_reasoning_v2.py; run from ~/freca/core_v1"
    )

if not NATURE.exists():
    raise SystemExit(
        "Missing evidence_nature_v1.py; install EvidenceNature v1.1 first"
    )

source = TARGET.read_text(encoding="utf-8")

required_markers = (
    "SUPPORT_COMBINED_BASELINE",
    "ATTACK_VARIANT_UNION_PLUS_STRUCTURE",
    "VARIANT_TOP",
    "STRUCTURE_NEIGHBOUR",
)

missing = [
    marker
    for marker in required_markers
    if marker not in source
]

if missing:
    raise SystemExit(
        "Unexpected retrieval version. Missing markers: "
        + ", ".join(missing)
    )


def replace_function(
    src: str,
    name: str,
    replacement: str,
) -> str:
    tree = ast.parse(src)

    matches = [
        node
        for node in tree.body
        if isinstance(
            node,
            (
                ast.FunctionDef,
                ast.AsyncFunctionDef,
            ),
        )
        and node.name == name
    ]

    if len(matches) != 1:
        raise SystemExit(
            f"Expected one top-level {name}, found {len(matches)}"
        )

    node = matches[0]
    lines = src.splitlines(
        keepends=True
    )

    lines[
        node.lineno - 1:
        node.end_lineno
    ] = [
        'def retrieve_requirement_candidates(\n    evidence_chunks: list[dict],\n    needs: list[dict],\n    *,\n    top_k: int = 12,\n) -> list[dict]:\n    from evidence_nature_v1 import (\n        classify_evidence_nature,\n        infer_requirement_predicate_profile,\n    )\n\n    docs = []\n    by_id = {}\n\n    for chunk in evidence_chunks:\n        cid = chunk_id(chunk)\n        text = chunk_text(chunk)\n        item = dict(chunk)\n        item["id"] = cid\n        item["text"] = text\n        docs.append(item)\n        by_id[cid] = item\n\n    candidate_limit = 40\n    rrf_k = 60\n    per_variant_quota = 3\n    support_context_cap = max(24, top_k)\n    attack_context_cap = max(24, top_k)\n\n    bm25_cache = {}\n\n    def rank_query(query: str, limit: int) -> list[dict]:\n        query = normalize_ws(query)\n        cache_key = query + "\\n" + str(limit)\n\n        if cache_key not in bm25_cache:\n            bm25_cache[cache_key] = core.bm25_rank(\n                query,\n                docs,\n                limit,\n            )\n\n        return bm25_cache[cache_key]\n\n    def neighbour_ids(evidence_id: str) -> list[str]:\n        out = []\n\n        paragraph = re.match(\n            r"^(.*):P(\\d+)$",\n            evidence_id,\n        )\n\n        if paragraph:\n            prefix = paragraph.group(1)\n            number = int(paragraph.group(2))\n\n            for adjacent in (\n                number - 1,\n                number + 1,\n            ):\n                if adjacent >= 1:\n                    out.append(\n                        f"{prefix}:P{adjacent}"\n                    )\n\n            return out\n\n        row = re.match(\n            r"^(.*):R(\\d+)$",\n            evidence_id,\n        )\n\n        if row:\n            prefix = row.group(1)\n            number = int(row.group(2))\n\n            for adjacent in (\n                number - 1,\n                number + 1,\n            ):\n                if adjacent >= 1:\n                    out.append(\n                        f"{prefix}:R{adjacent}"\n                    )\n\n        return out\n\n    def rrf_order(\n        rankings: list[list[str]],\n    ) -> tuple[list[str], dict[str, float]]:\n        totals = {}\n        best_rank = {}\n        first_seen = {}\n        counter = 0\n\n        for ranking in rankings:\n            for rank, evidence_id in enumerate(\n                ranking,\n                start=1,\n            ):\n                totals[evidence_id] = (\n                    totals.get(\n                        evidence_id,\n                        0.0,\n                    )\n                    + 1.0 / (\n                        rrf_k + rank\n                    )\n                )\n\n                best_rank[evidence_id] = min(\n                    best_rank.get(\n                        evidence_id,\n                        10**9,\n                    ),\n                    rank,\n                )\n\n                if evidence_id not in first_seen:\n                    first_seen[evidence_id] = counter\n                    counter += 1\n\n        ordered = sorted(\n            totals,\n            key=lambda evidence_id: (\n                -totals[evidence_id],\n                best_rank[evidence_id],\n                first_seen[evidence_id],\n                evidence_id,\n            ),\n        )\n\n        return ordered, totals\n\n    # Minimal Core TYPED_FACT mapping.\n    # These are neutral evidence kinds used only for candidate discovery.\n    typed_natures_by_target = {\n        "DESIGN_CONSTRUCTION": {\n            "PHYSICAL_DESIGN_FEATURE",\n            "DESIGN_OR_CONSTRUCTION_DEFECT",\n        },\n        "CURRENT_CONDITION": {\n            "CURRENT_CONDITION",\n            "OBSERVATION_RECORD",\n            "REVIEW_FINDING",\n            "ACTIVITY_RECORD",\n            "CURRENT_MAINTENANCE_OR_CONDITION_DEFECT",\n            "ADVERSE_OPERATIONAL_FINDING",\n            "EXPLICIT_CONTROL_ABSENCE",\n        },\n        "ACTIVITY_PERFORMED": {\n            "ACTIVITY_RECORD",\n            "OBSERVATION_RECORD",\n            "REVIEW_FINDING",\n            "PROCEDURE_STATEMENT",\n            "PLAN_STATEMENT",\n        },\n        "RECORDKEEPING": {\n            "RECORD_EXISTS",\n            "ACTIVITY_RECORD",\n            "DOCUMENTATION_GAP",\n        },\n        "DOCUMENTATION": {\n            "RECORD_EXISTS",\n            "ACTIVITY_RECORD",\n            "DOCUMENTATION_GAP",\n        },\n        "PROCEDURE_OR_PLAN_EXISTS": {\n            "PROCEDURE_STATEMENT",\n            "PLAN_STATEMENT",\n            "DOCUMENTATION_GAP",\n        },\n        "OUTCOME_STATE": {\n            "CURRENT_CONDITION",\n            "OBSERVATION_RECORD",\n            "REVIEW_FINDING",\n            "CURRENT_MAINTENANCE_OR_CONDITION_DEFECT",\n            "ADVERSE_OPERATIONAL_FINDING",\n        },\n    }\n\n    typed_cache = {}\n\n    def typed_record(item: dict) -> dict:\n        evidence_id = item["id"]\n\n        if evidence_id not in typed_cache:\n            typed_cache[evidence_id] = (\n                classify_evidence_nature(\n                    item["text"]\n                )\n            )\n\n        return typed_cache[evidence_id]\n\n    def typed_candidates_for_need(\n        need: dict,\n    ) -> tuple[list[str], dict]:\n        facets = need.get(\n            "query_facets",\n            [],\n        )\n\n        proposition = (\n            facets[-1]\n            if facets\n            else ""\n        )\n\n        pseudo_requirement = {\n            "proposition_to_establish":\n                proposition,\n            "query_sources": [],\n        }\n\n        profile = (\n            infer_requirement_predicate_profile(\n                pseudo_requirement\n            )\n        )\n\n        target_kinds = profile.get(\n            "target_kinds",\n            [],\n        )\n\n        wanted = set()\n\n        for target_kind in target_kinds:\n            wanted.update(\n                typed_natures_by_target.get(\n                    target_kind,\n                    set(),\n                )\n            )\n\n        if not wanted:\n            return [], {\n                "target_kinds":\n                    target_kinds,\n                "wanted_natures":\n                    [],\n                "scan_chunk_count":\n                    len(docs),\n                "matched_count":\n                    0,\n            }\n\n        matched = []\n\n        for item in docs:\n            typed = typed_record(\n                item\n            )\n\n            natures = set(\n                typed.get(\n                    "evidence_natures",\n                    [],\n                )\n            )\n\n            if natures & wanted:\n                matched.append(\n                    item["id"]\n                )\n\n        return matched, {\n            "target_kinds":\n                target_kinds,\n            "wanted_natures":\n                sorted(wanted),\n            "scan_chunk_count":\n                len(docs),\n            "matched_count":\n                len(matched),\n        }\n\n    traces = []\n\n    for need in needs:\n        combined_query = _build_query(\n            need["query_facets"]\n        )\n\n        # SUPPORT now gets the same source-grounded lexical variant discipline\n        # as ATTACK, plus a full-case typed-fact discovery channel.\n        if need["direction"] == "SUPPORT":\n            variant_rows = []\n            rankings = []\n\n            for variant in need.get(\n                "query_variants",\n                [],\n            ):\n                query = normalize_ws(\n                    variant.get(\n                        "query",\n                        "",\n                    )\n                )\n\n                if not query:\n                    continue\n\n                ranked = rank_query(\n                    query,\n                    candidate_limit,\n                )\n\n                ids = [\n                    item["id"]\n                    for item in ranked\n                ]\n\n                rankings.append(ids)\n\n                variant_rows.append(\n                    {\n                        **variant,\n                        "candidate_limit":\n                            candidate_limit,\n                        "top_ids":\n                            ids[:per_variant_quota],\n                    }\n                )\n\n            if not rankings:\n                ranked = rank_query(\n                    combined_query,\n                    candidate_limit,\n                )\n\n                ids = [\n                    item["id"]\n                    for item in ranked\n                ]\n\n                rankings = [ids]\n\n                variant_rows = [\n                    {\n                        "variant_id":\n                            f"{need[\'need_id\']}.fallback",\n                        "source":\n                            "COMBINED",\n                        "candidate_id":\n                            None,\n                        "query":\n                            combined_query,\n                        "transformation":\n                            "COMBINED_FALLBACK",\n                        "candidate_limit":\n                            candidate_limit,\n                        "top_ids":\n                            ids[:per_variant_quota],\n                    }\n                ]\n\n            fused_ids, rrf_scores = (\n                rrf_order(\n                    rankings\n                )\n            )\n\n            (\n                typed_ids,\n                typed_trace,\n            ) = typed_candidates_for_need(\n                need\n            )\n\n            ordered_ids = []\n            methods_by_id = {}\n\n            def add_support_candidate(\n                evidence_id: str,\n                method: str,\n            ) -> None:\n                if evidence_id not in by_id:\n                    return\n\n                methods_by_id.setdefault(\n                    evidence_id,\n                    [],\n                )\n\n                if method not in methods_by_id[\n                    evidence_id\n                ]:\n                    methods_by_id[\n                        evidence_id\n                    ].append(\n                        method\n                    )\n\n                if evidence_id not in ordered_ids:\n                    ordered_ids.append(\n                        evidence_id\n                    )\n\n            # Typed channel first so lexical wording cannot crowd actual-status\n            # evidence out of the model context.\n            for evidence_id in typed_ids:\n                add_support_candidate(\n                    evidence_id,\n                    "TYPED_FACT_SCAN",\n                )\n\n            for variant in variant_rows:\n                for evidence_id in variant[\n                    "top_ids"\n                ]:\n                    add_support_candidate(\n                        evidence_id,\n                        "VARIANT_TOP",\n                    )\n\n            # Structural rescue around both typed and lexical seeds.\n            for evidence_id in list(\n                ordered_ids\n            ):\n                for neighbour_id in neighbour_ids(\n                    evidence_id\n                ):\n                    add_support_candidate(\n                        neighbour_id,\n                        "STRUCTURE_NEIGHBOUR",\n                    )\n\n            for evidence_id in fused_ids:\n                if len(\n                    ordered_ids\n                ) >= support_context_cap:\n                    break\n\n                add_support_candidate(\n                    evidence_id,\n                    "RRF_FILL",\n                )\n\n            ordered_ids = ordered_ids[\n                :support_context_cap\n            ]\n\n            candidates = []\n\n            for evidence_id in ordered_ids:\n                item = by_id[\n                    evidence_id\n                ]\n\n                candidates.append(\n                    {\n                        "evidence_id":\n                            evidence_id,\n                        "score":\n                            rrf_scores.get(\n                                evidence_id\n                            ),\n                        "text":\n                            item["text"],\n                        "retrieval_methods":\n                            methods_by_id.get(\n                                evidence_id,\n                                [],\n                            ),\n                    }\n                )\n\n            traces.append(\n                {\n                    **need,\n                    "query":\n                        combined_query,\n                    "query_plan_mode":\n                        "SUPPORT_VARIANT_UNION_TYPED_PLUS_STRUCTURE",\n                    "query_variants":\n                        variant_rows,\n                    "typed_fact_scan":\n                        typed_trace,\n                    "top_k":\n                        top_k,\n                    "candidate_limit":\n                        candidate_limit,\n                    "per_variant_quota":\n                        per_variant_quota,\n                    "support_context_cap":\n                        support_context_cap,\n                    "candidate_count_checked_by_model":\n                        len(candidates),\n                    "retrieval_scan_chunk_count":\n                        len(docs),\n                    "coverage_status":\n                        "VARIANT_TYPED_STRUCTURE_PILOT",\n                    "candidates":\n                        candidates,\n                }\n            )\n\n            continue\n\n        # ATTACK branch preserved from the already validated patch.\n        variant_rows = []\n        rankings = []\n\n        for variant in need.get(\n            "query_variants",\n            [],\n        ):\n            query = normalize_ws(\n                variant.get(\n                    "query",\n                    "",\n                )\n            )\n\n            if not query:\n                continue\n\n            ranked = rank_query(\n                query,\n                candidate_limit,\n            )\n\n            ids = [\n                item["id"]\n                for item in ranked\n            ]\n\n            rankings.append(ids)\n\n            variant_rows.append(\n                {\n                    **variant,\n                    "candidate_limit":\n                        candidate_limit,\n                    "top_ids":\n                        ids[:per_variant_quota],\n                }\n            )\n\n        if not rankings:\n            ranked = rank_query(\n                combined_query,\n                candidate_limit,\n            )\n\n            ids = [\n                item["id"]\n                for item in ranked\n            ]\n\n            rankings = [ids]\n\n            variant_rows = [\n                {\n                    "variant_id":\n                        f"{need[\'need_id\']}.fallback",\n                    "source":\n                        "COMBINED",\n                    "candidate_id":\n                        None,\n                    "query":\n                        combined_query,\n                    "transformation":\n                        "COMBINED_FALLBACK",\n                    "candidate_limit":\n                        candidate_limit,\n                    "top_ids":\n                        ids[:per_variant_quota],\n                }\n            ]\n\n        fused_ids, rrf_scores = (\n            rrf_order(\n                rankings\n            )\n        )\n\n        ordered_ids = []\n        methods_by_id = {}\n\n        def add_attack_candidate(\n            evidence_id: str,\n            method: str,\n        ) -> None:\n            if evidence_id not in by_id:\n                return\n\n            methods_by_id.setdefault(\n                evidence_id,\n                [],\n            )\n\n            if method not in methods_by_id[\n                evidence_id\n            ]:\n                methods_by_id[\n                    evidence_id\n                ].append(\n                    method\n                )\n\n            if evidence_id not in ordered_ids:\n                ordered_ids.append(\n                    evidence_id\n                )\n\n        for variant in variant_rows:\n            for evidence_id in variant[\n                "top_ids"\n            ]:\n                add_attack_candidate(\n                    evidence_id,\n                    "VARIANT_TOP",\n                )\n\n                for neighbour_id in neighbour_ids(\n                    evidence_id\n                ):\n                    add_attack_candidate(\n                        neighbour_id,\n                        "STRUCTURE_NEIGHBOUR",\n                    )\n\n        for evidence_id in fused_ids:\n            if len(\n                ordered_ids\n            ) >= attack_context_cap:\n                break\n\n            add_attack_candidate(\n                evidence_id,\n                "RRF_FILL",\n            )\n\n        ordered_ids = ordered_ids[\n            :attack_context_cap\n        ]\n\n        candidates = []\n\n        for evidence_id in ordered_ids:\n            item = by_id[\n                evidence_id\n            ]\n\n            candidates.append(\n                {\n                    "evidence_id":\n                        evidence_id,\n                    "score":\n                        rrf_scores.get(\n                            evidence_id\n                        ),\n                    "text":\n                        item["text"],\n                    "retrieval_methods":\n                        methods_by_id.get(\n                            evidence_id,\n                            [],\n                        ),\n                }\n            )\n\n        traces.append(\n            {\n                **need,\n                "query":\n                    combined_query,\n                "query_plan_mode":\n                    "ATTACK_VARIANT_UNION_PLUS_STRUCTURE",\n                "query_variants":\n                    variant_rows,\n                "top_k":\n                    top_k,\n                "candidate_limit":\n                    candidate_limit,\n                "per_variant_quota":\n                    per_variant_quota,\n                "attack_context_cap":\n                    attack_context_cap,\n                "candidate_count_checked_by_model":\n                    len(candidates),\n                "retrieval_scan_chunk_count":\n                    len(docs),\n                "coverage_status":\n                    "VARIANT_UNION_STRUCTURE_PILOT",\n                "candidates":\n                    candidates,\n            }\n        )\n\n    return traces\n'.rstrip()
        + "\n\n"
    ]

    return "".join(lines)


